diff --git a/Sources/SwiftJLI/Native/Decoder/JLIDecoder.swift b/Sources/SwiftJLI/Native/Decoder/JLIDecoder.swift
index e0bf380..cf62699 100644
--- a/Sources/SwiftJLI/Native/Decoder/JLIDecoder.swift
+++ b/Sources/SwiftJLI/Native/Decoder/JLIDecoder.swift
@@ -1099,7 +1099,10 @@ struct JLIDecoder: Sendable {
                 // scan mode, while retaining the identical entropy reader.
                 var value = segmentY == 0 ? half : row[0]
                 for x in 0..<w {
-                    value = (value + (try losslessLookupDifference(table, &reader, lookup))) & 0xFFFF
+                    let difference: Int32
+                    if let decoded = reader.fastDecodeLosslessDifference(lookup) { difference = decoded }
+                    else { difference = try losslessDifference(table, &reader) }
+                    value = (value + difference) & 0xFFFF
                     if x == 0 { row[0] = value }
                     writeLosslessSample(value, outputRow, x, bps, pt)
                 }
@@ -1120,7 +1123,10 @@ struct JLIDecoder: Sendable {
                         default: predicted = (left + above) >> 1
                         }
                     }
-                    let value = (predicted + (try losslessLookupDifference(table, &reader, lookup))) & 0xFFFF
+                    let difference: Int32
+                    if let decoded = reader.fastDecodeLosslessDifference(lookup) { difference = decoded }
+                    else { difference = try losslessDifference(table, &reader) }
+                    let value = (predicted + difference) & 0xFFFF
                     row[x] = value
                     left = value
                     aboveLeft = above
@@ -1130,14 +1136,6 @@ struct JLIDecoder: Sendable {
         }
     }

-    @inline(__always)
-    private static func losslessLookupDifference(
-        _ table: HuffmanTable, _ reader: inout BitReader, _ lookup: LosslessLookahead
-    ) throws -> Int32 {
-        if let difference = reader.fastDecodeLosslessDifference(lookup) { return difference }
-        return try losslessDifference(table, &reader)
-    }
-
     /// Grayscale (single-component) lossless scan — the clinical hot loop.
     /// Straight-line per-sample body: predict (edge cases first, then the
     /// fixed-per-scan selector switch, which the branch predictor learns),
diff --git a/Sources/SwiftJLI/Native/Entropy/JLIBitStream.swift b/Sources/SwiftJLI/Native/Entropy/JLIBitStream.swift
index d322c1f..0a8f45f 100644
--- a/Sources/SwiftJLI/Native/Entropy/JLIBitStream.swift
+++ b/Sources/SwiftJLI/Native/Entropy/JLIBitStream.swift
@@ -192,7 +192,14 @@ struct BitReader {
         }
         guard !Self.hasFFByte(word) else { return false }
         let k = (64 - bitsAvailable) >> 3          // whole bytes that fit (≥ 6 here)
-        bitBuffer = (bitBuffer << (8 * k)) | (word >> (64 - 8 * k))
+        // Refill callers have 0...15 buffered bits. With an empty buffer,
+        // all eight bytes replace it; otherwise both shifts are within 1...63.
+        // Handle the 64-bit splice explicitly before using masked shifts.
+        if bitsAvailable == 0 {
+            bitBuffer = word
+        } else {
+            bitBuffer = (bitBuffer &<< (8 * k)) | (word &>> (64 - 8 * k))
+        }
         bitsAvailable += 8 * k
         byteOffset += k
         return true
@@ -266,7 +273,10 @@ struct BitReader {
     mutating func fastDecodeLosslessDifference(_ table: LosslessLookahead) -> Int32? {
         if bitsAvailable < LosslessLookahead.bits, !bulkRefill() { fillBuffer(upTo: 8) }
         guard bitsAvailable >= LosslessLookahead.bits else { return nil }
-        let prefix = Int((bitBuffer >> (bitsAvailable - LosslessLookahead.bits)) & UInt64(LosslessLookahead.count - 1))
+        // All reader mutations keep bitsAvailable in 0...64. The guard
+        // bounds this shift to 0...51, so masking preserves the checked
+        // shift's value without its general-purpose signed-width branches.
+        let prefix = Int((bitBuffer &>> (bitsAvailable - LosslessLookahead.bits)) & UInt64(LosslessLookahead.count - 1))
         let entry = table.entries[prefix]
         guard entry != 0 else { return nil }
         bitsAvailable -= Int(entry >> 16)
